import {projectRecords} from './services.mjs';
import {portfolioPage,portfolioSEO} from './cms/portfolio.mjs';
import {esc} from './cms/runtime.mjs';
import {renderContent} from './content.mjs';
export async function portfolioRoutes(request,env,url){const m=url.pathname.match(/^\/satin(?:\/(fa|fr|es))?\/portfolio(?:\/(commercial|colour-change)|\/projects\/([a-z0-9-]+))?\/?$/);if(!m)return null;const lang=m[1]||'en',path='/portfolio'+(m[2]?'/'+m[2]:m[3]?'/projects/'+m[3]:''),page=portfolioPage(lang,path,url.searchParams,(await projectRecords(env.DB)).filter(p=>p.active!==false));if(!page)return new Response('Project not found',{status:404,headers:{'X-Robots-Tag':'noindex'}});const template=await env.ASSETS.fetch(new Request(new URL('/satin'+(lang==='en'?'':'/'+lang)+'/',url),request));if(!template.ok)return template;let html=await template.text();const seo=portfolioSEO(lang,path,page,url.searchParams);let i=0,section=0;let content=page.html.replace(/<(?:h[1-4]|p|img|a(?=\s[^>]*class="btn)|span(?=\s[^>]*class="eyebrow))\b/g,tag=>tag+' data-cms-id="e'+i+++'"').replace(/<section\b/g,tag=>tag+' data-cms-section="s'+section+++'"');html=html.replace(/(<main\b[^>]*>)[\s\S]*?(<\/main>)/,(_,a,b)=>a+'<div class="page-enter">'+content+'</div>'+b).replace(/data-prerender-path="[^"]*"/,'data-prerender-path="'+path+'"').replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(seo.title)+'</title>');
for(const [attr,key,val]of [['name','description',seo.description],['name','robots',seo.noindex?'noindex,follow':'index,follow'],['property','og:title',seo.title],['name','twitter:title',seo.title],['property','og:description',seo.description],['name','twitter:description',seo.description],['property','og:image',seo.image],['name','twitter:image',seo.image],['property','og:url',seo.canonical]])html=html.replace(new RegExp('(<meta '+attr+'="'+key+'" content=")[^"]*'),(_,a)=>a+esc(val));html=html.replace(/(<link rel="canonical" href=")[^"]*/,(_,a)=>a+esc(seo.canonical));html=html.replace(/<script type="application\/ld\+json" id="page-schema">[\s\S]*?<\/script>/,'<script type="application/ld+json" id="page-schema">'+JSON.stringify(seo.jsonld).replace(/</g,'\\u003c')+'</script>');html=html.replace(/<link rel="alternate"[^>]*>/g,'');const href=l=>'https://satin-graphic-website.mehrad-tr.chatgpt.site/satin'+(l==='en'?'':'/'+l)+path+'/';const langs=['en','fa','fr','es'];html=html.replace('</head>','<link rel="stylesheet" href="/cms/portfolio.css">'+langs.map(l=>'<link rel="alternate" hreflang="'+l+'" href="'+href(l)+'">').join('')+'<link rel="alternate" hreflang="x-default" href="'+href('en')+'"></head>');return renderContent(new Response(html,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store'}}),request,env);}